package cl.bolsillo.app;
import android.content.*;import android.security.keystore.*;import android.util.Base64;import org.json.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
/** Private, device-encrypted cache and durable outbox. Never stores bank credentials. */
public final class NativeStore {
 private static final String ALIAS="BolsilloLocalV2";
 private static SecretKey key() throws Exception {KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(ALIAS))return (SecretKey)ks.getKey(ALIAS,null);KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return g.generateKey();}
 static synchronized JSONObject state(Context c)throws Exception {String value=c.getSharedPreferences("secure",0).getString("state",null);if(value==null)return new JSONObject();String[] p=value.split(":",2);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(p[0],Base64.NO_WRAP)));return new JSONObject(new String(cipher.doFinal(Base64.decode(p[1],Base64.NO_WRAP)),"UTF-8"));}
 static synchronized void write(Context c,JSONObject state)throws Exception {LocalData.foldQueue(state);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String value=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(state.toString().getBytes("UTF-8")),Base64.NO_WRAP);if(!c.getSharedPreferences("secure",0).edit().putString("state",value).commit())throw new Exception("No se pudo guardar en el teléfono");settings(c).edit().putLong("lastSync",System.currentTimeMillis()).apply();}
 static synchronized JSONObject cached(Context c)throws Exception{return state(c).optJSONObject("cache");}
 static synchronized JSONArray queue(Context c)throws Exception {JSONArray a=state(c).optJSONArray("queue");return a==null?new JSONArray():a;}
 static synchronized void cache(Context c,JSONObject ledger)throws Exception {JSONObject s=state(c);s.put("cache",ledger);write(c,s);}
 static synchronized void enqueue(Context c,JSONObject tx)throws Exception {JSONObject s=state(c),cache=s.optJSONObject("cache");if(cache==null||cache.optString("ownerId").isEmpty())throw new Exception("Abre Bolsillo una vez para preparar tus cuentas locales.");JSONObject before=new JSONObject(cache.getJSONObject("data").toString());JSONArray q=s.optJSONArray("queue");if(q==null)q=new JSONArray();if(q.length()>=500)throw new Exception("Hay 500 registros pendientes. Sincroniza la app antes de continuar.");for(int i=0;i<q.length();i++)if(q.getJSONObject(i).optJSONObject("tx").optString("id").equals(tx.optString("id")))return;JSONObject entry=new JSONObject();entry.put("ownerId",cache.getString("ownerId"));entry.put("tx",tx);q.put(entry);s.put("queue",q);write(c,s);try{LocalAlerts.changed(c,before,s.getJSONObject("cache").getJSONObject("data"));}catch(Exception ignored){}SyncJob.schedule(c);}
 static synchronized void acknowledge(Context c,java.util.Set<String> ids,JSONObject latest)throws Exception {JSONObject s=state(c);JSONArray old=s.optJSONArray("queue"),q=new JSONArray();if(old!=null)for(int i=0;i<old.length();i++){JSONObject e=old.getJSONObject(i);if(!ids.contains(e.getJSONObject("tx").getString("id")))q.put(e);}s.put("queue",q);s.put("cache",latest);write(c,s);}
 static synchronized boolean markSeen(Context c,String id)throws Exception {JSONObject s=state(c);JSONArray old=s.optJSONArray("seen");if(old==null)old=new JSONArray();for(int i=0;i<old.length();i++)if(id.equals(old.optString(i)))return false;JSONArray next=new JSONArray();for(int i=Math.max(0,old.length()-999);i<old.length();i++)next.put(old.getString(i));next.put(id);s.put("seen",next);write(c,s);return true;}
 static synchronized void saveDetection(Context c,JSONObject evidence,JSONObject tx)throws Exception{JSONObject s=state(c),cache=s.optJSONObject("cache");if(cache==null||!cache.optString("ownerId").equals(evidence.optString("ownerId")))throw new Exception("La sesión cambió");JSONArray seen=s.optJSONArray("seen");if(seen==null)seen=new JSONArray();for(int i=0;i<seen.length();i++)if(evidence.getString("id").equals(seen.optString(i)))return;JSONArray inbox=s.optJSONArray("detectionInbox");if(inbox==null)inbox=new JSONArray();JSONArray q=s.optJSONArray("queue");if(q==null)q=new JSONArray();if(tx==null&&!evidence.optBoolean("suppressed")){if(inbox.length()>=500)throw new Exception("Revisa las detecciones pendientes");inbox.put(evidence);}else if(tx!=null){if(q.length()>=500)throw new Exception("Sincroniza los registros pendientes");q.put(new JSONObject().put("ownerId",cache.getString("ownerId")).put("tx",tx));}seen.put(evidence.getString("id"));s.put("seen",tail(seen,1000));JSONArray events=s.optJSONArray("detectionEvents");if(events==null)events=new JSONArray();events.put(evidence);s.put("detectionEvents",tail(events,1000));s.put("detectionInbox",inbox);s.put("queue",q);write(c,s);try{LocalAlerts.detected(c,evidence,tx);}catch(Exception ignored){}if(tx!=null)SyncJob.schedule(c);}
 static JSONArray tail(JSONArray values,int count)throws Exception{JSONArray next=new JSONArray();for(int i=Math.max(0,values.length()-count);i<values.length();i++)next.put(values.get(i));return next;}
 static synchronized void resolveDetection(Context c,String id,JSONObject tx)throws Exception{java.util.LinkedHashMap<String,JSONObject> requested=new java.util.LinkedHashMap<>();requested.put(id,tx);resolveDetections(c,requested);}
 /** Confirm a group with one encrypted commit: a failed validation changes none of them. */
 static synchronized void resolveDetections(Context c,java.util.Map<String,JSONObject> requested)throws Exception{
  JSONObject s=state(c),cache=s.optJSONObject("cache");JSONArray old=s.optJSONArray("detectionInbox"),next=new JSONArray();if(cache==null)return;if(old==null)old=new JSONArray();JSONObject prior=new JSONObject(cache.getJSONObject("data").toString());java.util.Map<String,java.util.Map<String,String>> before=ChangeHistory.snapshot(cache.getJSONObject("data"));boolean pendingChanged=false;
  java.util.LinkedHashMap<JSONObject,JSONObject> resolved=new java.util.LinkedHashMap<>();JSONArray q=s.optJSONArray("queue");if(q==null)q=new JSONArray();
  for(int i=0;i<old.length();i++){JSONObject e=old.getJSONObject(i);String id=e.optString("id");if(!requested.containsKey(id)||!cache.optString("ownerId").equals(e.optString("ownerId"))){next.put(e);continue;}JSONObject tx=requested.get(id);if(tx!=null){if(q.length()>=500)throw new Exception("Sincroniza primero");LearnedRules.confirmed(cache.getJSONObject("data"),e,tx);e.put("confirmedByUser",true).put("type",tx.optString("type")).put("amount",tx.optLong("amount")).put("merchant",tx.optString("note")).put("account",tx.optString("account")).put("category",tx.optString("category"));q.put(new JSONObject().put("ownerId",cache.getString("ownerId")).put("tx",tx));}resolved.put(e,tx);JSONArray events=s.optJSONArray("detectionEvents");if(events!=null)for(int j=0;j<events.length();j++){JSONObject event=events.getJSONObject(j);if(id.equals(event.optString("id"))){event.put("resolvedAt",System.currentTimeMillis()).put("resolution",tx==null?"discarded":"confirmed");if(tx!=null){if(event.optLong("amount")!=tx.optLong("amount"))event.put("parsedAmount",event.optLong("amount"));event.put("txId",tx.getString("id")).put("account",tx.getString("account")).put("category",tx.optString("category")).put("amount",tx.optLong("amount")).put("type",tx.optString("type")).put("merchant",tx.optString("note")).put("confirmedByUser",true);}}}
  }
  JSONArray transactions=cache.getJSONObject("data").getJSONArray("transactions");for(java.util.Map.Entry<String,JSONObject> request:requested.entrySet())if(request.getKey().startsWith("pending:")){String id=request.getKey().substring(8);for(int i=transactions.length()-1;i>=0;i--){JSONObject pending=transactions.getJSONObject(i);if(!id.equals(pending.optString("id"))||!pending.optString("status").equals("pending"))continue;if(request.getValue()==null)transactions.remove(i);else pending.put("status","posted");pendingChanged=true;}}
  if(resolved.isEmpty()&&!pendingChanged)return;if(pendingChanged){Ledger.validate(cache.getJSONObject("data"));ChangeHistory.record(cache.getJSONObject("data"),before);}s.put("queue",q).put("detectionInbox",next);write(c,s);if(pendingChanged)LocalAlerts.changed(c,prior,s.getJSONObject("cache").getJSONObject("data"));
  for(java.util.Map.Entry<JSONObject,JSONObject> row:resolved.entrySet())try{if(row.getValue()!=null)LocalAlerts.detected(c,row.getKey(),row.getValue());else LocalAlerts.resolved(c,row.getKey().optString("id"),null);}catch(Exception ignored){}
  SyncJob.schedule(c);
 }
   static synchronized void logNotice(Context c,JSONObject source,String result,long at)throws Exception{JSONObject s=state(c);JSONArray log=s.optJSONArray("notificationLog");if(log==null)log=new JSONArray();log.put(new JSONObject().put("at",at).put("app",source.optString("label")).put("result",result));s.put("notificationLog",tail(log,150));write(c,s);}
   static SharedPreferences settings(Context c){return c.getSharedPreferences("settings-v2",0);}
}

